prlimit --nofile=32:32 -- python3 - <<'PY'
import errno
pliki = []
try:
    while True:
        pliki.append(open("/dev/null", "rb"))
except OSError as blad:
    assert blad.errno == errno.EMFILE
    print("EMFILE: per-process descriptor limit")
finally:
    for plik in pliki:
        plik.close()
PY
